  const times = [0,800,1530,2330,3130,3930,4670,5470];
  // Corresponding points run from the crown around both feet and up the jaw.
  const contours = [
    `100 18,115 22,122 35,123 48,131 67,139 94,148 126,156 164,156 190,141 220,135 249,124 315,102 315,98 231,95 315,73 315,68 263,60 229,48 200,40 174,41 149,48 116,53 85,63 62,76 44,84 28,91 21`,
