    [77.3,51.6,100,50.5,4.8,1.55],[80.5,57.3,86,60.9,1,1],
    [83,58.3,89.1,62.5,1,.92],[75.2,58,81.7,62,.8,1]
  ];
  // Shoulder, elbow, wrist, radii, hand angle, width, length, spread, and visibility over the body.
  const leftArms = [
    [64,72,49,121,35,185,12,7,4.8,17,.9,1.02,.15,0],
    [47,98,50,129,71,88,11.5,12.3,6.1,-130,1.13,.83,.3,1],
