    [105,99,127,157,152,218,14,11.1,6.8,-30,1.03,.96,.56,1]
  ];
  const rightArms = [
    [121,66,138,105,157,192,10.5,6.6,5.2,-13,.91,.99,.08,0],
    [99,95,109,111,107,89,10,10.8,6,148,1.08,.85,.27,1],
    [119,89,153,134,170,128,10.7,10.5,5.8,-72,.95,.82,-.23,1],
