    [96,89,57,108,29,90,10.6,8.3,5.2,113,.72,1.03,-.26,0],
    [106,97,63,119,29,98,11.3,8.7,5.6,111,.8,1.04,-.27,0],
    [112,94,121,148,135,199,10.8,7.8,5.3,-13,.83,.97,.2,0]
